#!/usr/bin/env node
/*
 * Workaround for a Sentio SDK 4 Sui codegen bug (@typemove/sui <= 2.0.5).
 *
 * When a fetched Move package contains a module and a struct with the SAME name
 * (e.g. a module `TOKEN` that also defines a struct `TOKEN`), codegen emits a
 * nested `export namespace TOKEN { ... export namespace TOKEN { ... } }`. Intra-
 * module references then resolve to the inner (struct) namespace instead of the
 * module, producing dozens of TS2694 "has no exported member" errors in the
 * generated file — which is a transitive dependency we don't even author.
 *
 * `src/types/**` is gitignored and regenerated by `sentio gen`, so we can't fix
 * the file in source. Instead this script re-applies a `// @ts-nocheck` to any
 * generated Sui type file that has the self-nested same-name namespace collision.
 * It is wired into the package.json gen/build/upload scripts so it runs after
 * every codegen. Remove once the upstream codegen bug is fixed.
 */
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'

const here = dirname(fileURLToPath(import.meta.url))
const typesDir = join(here, '..', 'src', 'types', 'sui')

let dir
try {
  dir = readdirSync(typesDir)
} catch {
  console.log('[patch-sui-codegen] no src/types/sui dir; nothing to do')
  process.exit(0)
}

// Returns true iff the file declares a namespace nested inside another
// namespace of the SAME name (the codegen bug). Sibling same-name namespaces
// (valid TS declaration merging) and same-name namespaces in different modules
// are NOT flagged. Strings/comments are blanked first so their braces don't
// throw off the brace-depth stack.
function hasSelfNestedNamespace(src) {
  const cleaned = src
    .replace(/\/\*[\s\S]*?\*\//g, '') // block comments
    .replace(/\/\/[^\n]*/g, '') // line comments
    .replace(/`(?:\\.|[^`\\])*`/g, '``') // template literals
    .replace(/"(?:\\.|[^"\\])*"/g, '""') // double-quoted
    .replace(/'(?:\\.|[^'\\])*'/g, "''") // single-quoted
  const token = /export\s+namespace\s+(\w+)\s*\{|\{|\}/g
  const stack = [] // frames: { ns: <name|null> }
  let m
  while ((m = token.exec(cleaned))) {
    if (m[1]) {
      if (stack.some((f) => f.ns === m[1])) return true // same name already open above
      stack.push({ ns: m[1] })
    } else if (m[0] === '{') {
      stack.push({ ns: null })
    } else {
      stack.pop()
    }
  }
  return false
}

let patched = 0
for (const file of dir) {
  if (!file.endsWith('.ts')) continue
  const path = join(typesDir, file)
  const content = readFileSync(path, 'utf8')
  if (content.startsWith('// @ts-nocheck')) continue
  if (!hasSelfNestedNamespace(content)) continue
  writeFileSync(path, '// @ts-nocheck\n' + content)
  patched++
  console.log(`[patch-sui-codegen] @ts-nocheck applied to src/types/sui/${file} (self-nested same-name namespace collision)`)
}
if (patched === 0) console.log('[patch-sui-codegen] no collision files found; nothing to patch')
